  <script>
    const fields = Array.from(document.querySelectorAll("#otp-fields input"));
    const form = document.getElementById("otp-form");
    const status = document.getElementById("status");
    const verifyButton = document.getElementById("verify");
    const countdownText = document.getElementById("countdown");
    const resendButton = document.getElementById("resend");
    let remaining = 45;
    let timer;

    function updateCompletion() {
      const complete = fields.every((field) => field.value.trim() !== "");
      verifyButton.disabled = !complete;
    }

    fields.forEach((field, index) => {
      field.addEventListener("input", () => {
        field.value = field.value.replace(/\D/g, "").slice(0, 1);
        status.textContent = "";

        if (field.value && index < fields.length - 1) {
          fields[index + 1].focus();
        }

        updateCompletion();
      });

      field.addEventListener("keydown", (event) => {
        if (event.key === "Backspace" && !field.value && index > 0) {
          fields[index - 1].focus();
        }

        if (event.key === "ArrowLeft" && index < fields.length - 1) {
          fields[index + 1].focus();
        }

        if (event.key === "ArrowRight" && index > 0) {
          fields[index - 1].focus();
        }
      });

      field.addEventListener("paste", (event) => {
        const pasted = (event.clipboardData.getData("text") || "").replace(/\D/g, "");
        if (pasted.length) {
          event.preventDefault();
          pasted.split("").slice(0, fields.length).forEach((digit, digitIndex) => {
            fields[digitIndex].value = digit;
          });
          fields[Math.min(pasted.length, fields.length) - 1].focus();
          updateCompletion();
        }
      });
    });

    function renderCountdown() {
      if (remaining <= 0) {
        clearInterval(timer);
        countdownText.hidden = true;
        resendButton.hidden = false;
        resendButton.disabled = false;
        return;
      }

      const minutes = Math.floor(remaining / 60);
      const seconds = String(remaining % 60).padStart(2, "0");
      countdownText.innerHTML = `إعادة الإرسال خلال <bdi dir="ltr">${minutes}:${seconds}</bdi>`;
      remaining -= 1;
    }

    resendButton.addEventListener("click", () => {
      remaining = 45;
      countdownText.hidden = false;
      resendButton.hidden = true;
      renderCountdown();
      timer = setInterval(renderCountdown, 1000);
      fields[0].focus();
    });

    form.addEventListener("submit", (event) => {
      event.preventDefault();
      const code = fields.map((field) => field.value).join("");

      if (code.length !== 6) {
        status.textContent = "يرجى إدخال الرمز بالكامل المكوّن من 6 أرقام.";
        return;
      }

      verifyButton.disabled = true;
      verifyButton.textContent = "جارٍ التحقق...";

      setTimeout(() => {
        verifyButton.textContent = "تأكيد الرمز";
        verifyButton.disabled = false;
        status.style.color = "var(--green-700)";
        status.textContent = "تم التحقق من الرمز بنجاح.";
      }, 900);
    });

    renderCountdown();
    timer = setInterval(renderCountdown, 1000);
  </script>
